state.failing_test:
def _is_prime(n: int) -> bool:
    """Obviously-correct reference model for primality of length."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    r = int(n ** 0.5)
    for d in range(3, r + 1, 2):
        if n % d == 0:
            return False
    return True

def _ref(string) -> bool:
    return _is_prime(len(string))

def _make_string(n: int) -> str:
    return "a" * n

@given(st.integers(min_value=0, max_value=200))
def test_adding_one_char_flips_according_to_reference(n):
    s = _make_string(n)
    t = s + "x"
    assert prime_length(s) == _is_prime(n)
    assert prime_length(t) == _is_prime(n + 1)
